@Override
public void endDocument() throws SAXException {
    if (documentEnded) {
        throw new SAXException("StrictXHTMLValidator: endDocument called twice");
    }
    if (!openElements.isEmpty()) {
        throw new SAXException("StrictXHTMLValidator: endDocument with " + openElements.size() + " unclosed element(s); topmost was <" + openElements.peek().qOrLocal() + ">");
    }
    documentEnded = true;
    super.endDocument();
}
